{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "header_title_stack",
        "intro_text",
        "symptoms_treatment_header_stack",
        "primary_symptoms_h3",
        "symptoms_list",
        "otc_treatment_h3",
        "otc_antihistamines_stack",
        "otc_decongestants_stack",
        "otc_nasal_corticosteroids_stack",
        "otc_eye_drops_stack",
        "prescription_treatment_h3",
        "prescription_nasal_sprays_stack",
        "prescription_leukotriene_modifiers_stack",
        "prescription_allergy_shots_stack",
        "prescription_slit_tablets_stack",
        "quick_actions_h2",
        "quick_actions_buttons_stack",
        "sources_h2",
        "sources_buttons_stack"
      ]
    },
    "header_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "title_icon_1",
        "title_h1"
      ]
    },
    "title_icon_1": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000744_01_1_tree.svg"
      },
      "children": []
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Pollen Allergy Insights for Adults (Ages 25-45)",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Seasonal allergies, often triggered by pollen from trees, grasses, and weeds, can significantly impact daily life. For adults aged 25-45, symptoms and treatment options are generally similar to those for other adult age groups, focusing on symptom relief and allergen avoidance."
      },
      "children": []
    },
    "symptoms_treatment_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "symptoms_treatment_icon",
        "symptoms_treatment_h2"
      ]
    },
    "symptoms_treatment_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000744_01_2_thermometer-half.svg"
      },
      "children": []
    },
    "symptoms_treatment_h2": {
      "type": "Text",
      "props": {
        "text": "Symptoms and Treatment Options",
        "variant": "h2"
      },
      "children": []
    },
    "primary_symptoms_h3": {
      "type": "Text",
      "props": {
        "text": "Primary Symptoms of Pollen Allergies",
        "variant": "h3"
      },
      "children": []
    },
    "symptoms_list": {
      "type": "List",
      "props": {},
      "children": [
        "symptom_1",
        "symptom_2",
        "symptom_3",
        "symptom_4",
        "symptom_5",
        "symptom_6",
        "symptom_7"
      ]
    },
    "symptom_1": {
      "type": "Text",
      "props": {
        "text": "Nasal Congestion: Stuffy nose, often accompanied by pressure."
      },
      "children": []
    },
    "symptom_2": {
      "type": "Text",
      "props": {
        "text": "Runny Nose: Clear, watery discharge from the nose."
      },
      "children": []
    },
    "symptom_3": {
      "type": "Text",
      "props": {
        "text": "Sneezing: Frequent and often uncontrollable sneezing."
      },
      "children": []
    },
    "symptom_4": {
      "type": "Text",
      "props": {
        "text": "Itchy Nose, Throat, and Eyes: A common and irritating symptom."
      },
      "children": []
    },
    "symptom_5": {
      "type": "Text",
      "props": {
        "text": "Watery Eyes: Eyes may appear red and feel gritty."
      },
      "children": []
    },
    "symptom_6": {
      "type": "Text",
      "props": {
        "text": "Cough: Often a dry cough, due to post-nasal drip."
      },
      "children": []
    },
    "symptom_7": {
      "type": "Text",
      "props": {
        "text": "Fatigue: Can result from poor sleep due to symptoms or the body's immune response."
      },
      "children": []
    },
    "otc_treatment_h3": {
      "type": "Text",
      "props": {
        "text": "Over-the-Counter (OTC) Treatment Options",
        "variant": "h3"
      },
      "children": []
    },
    "otc_antihistamines_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "otc_antihistamines_title",
        "otc_antihistamines_examples"
      ]
    },
    "otc_antihistamines_title": {
      "type": "Text",
      "props": {
        "text": "Antihistamines: Block histamine, reducing sneezing, itching, and runny nose."
      },
      "children": []
    },
    "otc_antihistamines_examples": {
      "type": "Text",
      "props": {
        "text": "Examples: Loratadine (Claritin), Cetirizine (Zyrtec), Fexofenadine (Allegra)."
      },
      "children": []
    },
    "otc_decongestants_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "otc_decongestants_title",
        "otc_decongestants_examples",
        "otc_decongestants_note"
      ]
    },
    "otc_decongestants_title": {
      "type": "Text",
      "props": {
        "text": "Decongestants: Reduce nasal stuffiness."
      },
      "children": []
    },
    "otc_decongestants_examples": {
      "type": "Text",
      "props": {
        "text": "Examples: Pseudoephedrine (Sudafed), Phenylephrine (Neo-Synephrine nasal spray)."
      },
      "children": []
    },
    "otc_decongestants_note": {
      "type": "Text",
      "props": {
        "text": "Note: Oral decongestants can raise blood pressure; nasal sprays should not be used for more than a few days to avoid rebound congestion."
      },
      "children": []
    },
    "otc_nasal_corticosteroids_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "otc_nasal_corticosteroids_title",
        "otc_nasal_corticosteroids_examples",
        "otc_nasal_corticosteroids_note"
      ]
    },
    "otc_nasal_corticosteroids_title": {
      "type": "Text",
      "props": {
        "text": "Nasal Corticosteroids: Reduce inflammation in the nasal passages, effective for congestion, sneezing, and runny nose."
      },
      "children": []
    },
    "otc_nasal_corticosteroids_examples": {
      "type": "Text",
      "props": {
        "text": "Examples: Fluticasone (Flonase), Budesonide (Rhinocort)."
      },
      "children": []
    },
    "otc_nasal_corticosteroids_note": {
      "type": "Text",
      "props": {
        "text": "Note: May take a few days to reach full effectiveness."
      },
      "children": []
    },
    "otc_eye_drops_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "otc_eye_drops_title",
        "otc_eye_drops_examples"
      ]
    },
    "otc_eye_drops_title": {
      "type": "Text",
      "props": {
        "text": "Eye Drops: Relieve itchy, watery eyes."
      },
      "children": []
    },
    "otc_eye_drops_examples": {
      "type": "Text",
      "props": {
        "text": "Examples: Ketotifen (Zaditor), Naphazoline (Clear Eyes Allergy)."
      },
      "children": []
    },
    "prescription_treatment_h3": {
      "type": "Text",
      "props": {
        "text": "Prescription Treatment Options",
        "variant": "h3"
      },
      "children": []
    },
    "prescription_nasal_sprays_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "prescription_nasal_sprays_title",
        "prescription_nasal_sprays_examples"
      ]
    },
    "prescription_nasal_sprays_title": {
      "type": "Text",
      "props": {
        "text": "Prescription Nasal Sprays: Stronger corticosteroids or antihistamine nasal sprays."
      },
      "children": []
    },
    "prescription_nasal_sprays_examples": {
      "type": "Text",
      "props": {
        "text": "Examples: Azelastine (Astelin, Astepro), Olopatadine (Patanase)."
      },
      "children": []
    },
    "prescription_leukotriene_modifiers_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "prescription_leukotriene_modifiers_title",
        "prescription_leukotriene_modifiers_examples"
      ]
    },
    "prescription_leukotriene_modifiers_title": {
      "type": "Text",
      "props": {
        "text": "Oral Leukotriene Modifiers: Block inflammatory chemicals, effective for both allergy and asthma symptoms."
      },
      "children": []
    },
    "prescription_leukotriene_modifiers_examples": {
      "type": "Text",
      "props": {
        "text": "Example: Montelukast (Singulair)."
      },
      "children": []
    },
    "prescription_allergy_shots_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "prescription_allergy_shots_title"
      ]
    },
    "prescription_allergy_shots_title": {
      "type": "Text",
      "props": {
        "text": "Allergy Shots (Immunotherapy): A long-term treatment involving regular injections of increasing doses of allergens to build tolerance. This can significantly reduce symptom severity over time."
      },
      "children": []
    },
    "prescription_slit_tablets_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "prescription_slit_tablets_title"
      ]
    },
    "prescription_slit_tablets_title": {
      "type": "Text",
      "props": {
        "text": "Sublingual Immunotherapy (SLIT) Tablets: Similar to allergy shots but administered as a tablet under the tongue, for specific pollen types."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "find_allergist_button",
        "pollen_forecast_button"
      ]
    },
    "find_allergist_button": {
      "type": "Button",
      "props": {
        "label": "Find an Allergist"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.aaaai.org/find-an-allergist"
          }
        }
      },
      "children": []
    },
    "pollen_forecast_button": {
      "type": "Button",
      "props": {
        "label": "Check Local Pollen Count"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.pollen.com/"
          }
        }
      },
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "aaaai_source_button",
        "mayo_clinic_source_button"
      ]
    },
    "aaaai_source_button": {
      "type": "Button",
      "props": {
        "label": "American Academy of Allergy, Asthma & Immunology (AAAAI)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.aaaai.org/conditions-treatments/allergies/seasonal-allergies"
          }
        }
      },
      "children": []
    },
    "mayo_clinic_source_button": {
      "type": "Button",
      "props": {
        "label": "Mayo Clinic"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.mayoclinic.org/diseases-conditions/hay-fever/symptoms-causes/syc-20373039"
          }
        }
      },
      "children": []
    }
  }
}
